-- ===========================================================================
-- Migration 024: the two resolutions migration 023 flagged for review
-- (31 Oct 2026). Their summaries were inverted, not just their targets.
--
--   H1IL0Y  sjres103-118  disapproval of the FCC 2024 Open Internet order.
--           The old row said the rule "repealed net neutrality"; it restored
--           it. Replaced with core.impact_drafts draft 15, regenerated by
--           "v2 Pipeline: impact statements" (n8n execution 14962) with the
--           corrected prompt: target = Title II + open internet rules, the
--           disapproval removes them.
--   KM5TYJ  sjres103-119 (bill level) and
--   J86UA12SYI  sjres103-119 pcs: disapproval of the VA Dec 2025 rule that
--           reinstated abortion exclusions. The regenerated draft (16) left
--           target_effect without a direction and contradicted itself, so it
--           was not used. Both rows take the statement already written for
--           the introduced text (CXIFMGMVJD, version is), which reads the
--           right way round; a disapproval resolution's text does not change
--           between introduced and placed-on-calendar.
--
-- Originals in core.bill_impacts_fix_024. content_changed_at moves so the
-- embeddings workflow re-embeds the three rows.
-- ===========================================================================

begin;

create table if not exists core.bill_impacts_fix_024 as
select *, now() as saved_at from core.bill_impacts where impact_id in ('H1IL0Y', 'KM5TYJ', 'J86UA12SYI');

update core.bill_impacts i set
  title = d.statement->>'title',
  policy_area = d.statement->>'policy_area_raw',
  primary_issue = d.statement->>'issue_primary',
  sub_issue = d.statement->>'issue_sub',
  keywords = d.statement->>'bill_keywords',
  intended_effects = d.statement->>'intended_effects',
  mechanisms = d.statement->>'mechanisms',
  summary = d.statement->>'neutral_summary',
  reverses_existing_policy = (d.statement->'regulatory_action'->>'reverses_existing_policy')::boolean,
  target_type = d.statement->'regulatory_action'->>'target_type',
  target_name = d.statement->'regulatory_action'->>'target_name',
  target_source = d.statement->'regulatory_action'->>'target_source',
  target_effect = d.statement->'regulatory_action'->>'target_effect',
  direction_confidence = (d.statement->'regulatory_action'->>'direction_confidence')::numeric,
  stakeholders = (select jsonb_agg(jsonb_build_object('stakeholder_uid', null, 'group', s->>'stakeholder_group',
                   'positive', s->>'positive_impact', 'negative', s->>'negative_impact'))
                  from jsonb_array_elements(d.statement->'affected_stakeholders') s),
  flagged_for_review = false,
  updated_at = now(),
  content_changed_at = now()
from core.impact_drafts d
where d.draft_id = 15 and d.bill_id = 'sjres103-118' and i.impact_id = 'H1IL0Y';

update core.bill_impacts i set
  title = s.title, policy_area = s.policy_area, primary_issue = s.primary_issue, sub_issue = s.sub_issue,
  keywords = s.keywords, intended_effects = s.intended_effects, mechanisms = s.mechanisms, summary = s.summary,
  reverses_existing_policy = s.reverses_existing_policy, target_type = s.target_type, target_name = s.target_name,
  target_source = s.target_source, target_effect = s.target_effect, direction_confidence = s.direction_confidence,
  stakeholders = s.stakeholders, flagged_for_review = false, updated_at = now(), content_changed_at = now()
from core.bill_impacts s
where s.impact_id = 'CXIFMGMVJD' and i.impact_id in ('KM5TYJ', 'J86UA12SYI');

commit;
